<?php
require_once '../config/database.php';require_once '../includes/auth.php';require_role('admin');$page_title='Студенты';
if($_SERVER['REQUEST_METHOD']==='POST'){
$id=(int)($_POST['id']??0);$surname=trim($_POST['surname']??'');$name=trim($_POST['name']??'');$patronymic=trim($_POST['patronymic']??'');$group=(int)($_POST['group_id']??0);$phone=trim($_POST['phone']??'');$email=trim($_POST['email']??'');$status=$_POST['status']??'active';
try{
if($surname===''||$name==='')throw new RuntimeException('Заполните фамилию и имя.');
if(!$group){throw new RuntimeException('Выберите группу.');}
$gq=$pdo->prepare('SELECT COUNT(*) FROM groups WHERE id=?');$gq->execute([$group]);if(!$gq->fetchColumn())throw new RuntimeException('Выбранная группа не найдена.');
if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Введите корректный email.');
if(!in_array($status,['active','inactive'],true))$status='active';
if(!$id){$login=trim($_POST['login']??'');$password=$_POST['password']??'';if(!preg_match('/^[A-Za-z0-9_.-]{3,100}$/',$login))throw new RuntimeException('Логин: 3–100 символов, латинские буквы, цифры, точка, дефис или _.');if(strlen($password)<6)throw new RuntimeException('Пароль должен содержать минимум 6 символов.');}
$pdo->beginTransaction();if($id){$pdo->prepare('UPDATE students SET surname=?,name=?,patronymic=?,group_id=?,phone=?,email=?,status=? WHERE id=?')->execute([$surname,$name,$patronymic,$group,$phone,$email,$status,$id]);$q=$pdo->prepare('SELECT user_id FROM students WHERE id=?');$q->execute([$id]);$uid=$q->fetchColumn();if($uid)$pdo->prepare('UPDATE users SET email=?,status=? WHERE id=?')->execute([$email,$status==='active'?'active':'blocked',$uid]);}
else{$login=trim($_POST['login']??'');$password=$_POST['password']??'';$pdo->prepare("INSERT INTO users(login,email,password,role,status) VALUES(?,?,?,'student','active')")->execute([$login,$email,password_hash($password,PASSWORD_DEFAULT)]);$uid=$pdo->lastInsertId();$pdo->prepare("INSERT INTO students(user_id,group_id,surname,name,patronymic,phone,email,status) VALUES(?,?,?,?,?,?,?,'active')")->execute([$uid,$group,$surname,$name,$patronymic,$phone,$email]);}$pdo->commit();$_SESSION['flash_success']='Данные студента сохранены.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['flash_error']=$e instanceof RuntimeException?$e->getMessage():'Не удалось сохранить студента. Возможно, логин уже занят.';}header('Location:students.php');exit;}
if(isset($_GET['delete'])){try{$s=$pdo->prepare('SELECT user_id FROM students WHERE id=?');$s->execute([(int)$_GET['delete']]);$uid=$s->fetchColumn();if(!$uid)throw new RuntimeException('Студент не найден.');$pdo->prepare('DELETE FROM users WHERE id=?')->execute([$uid]);$_SESSION['flash_success']='Студент и его аккаунт удалены.';}catch(Throwable $e){$_SESSION['flash_error']='Не удалось удалить студента.';}header('Location:students.php');exit;}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM students WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}
$groups=$pdo->query('SELECT * FROM groups ORDER BY name')->fetchAll();$qText=trim($_GET['q']??'');$groupFilter=(int)($_GET['group']??0);$statusFilter=$_GET['status']??'';
$sql="SELECT st.*,g.name group_name,u.login FROM students st JOIN groups g ON g.id=st.group_id JOIN users u ON u.id=st.user_id WHERE 1";$params=[];if($qText!==''){$sql.=' AND (st.surname LIKE ? OR st.name LIKE ? OR st.patronymic LIKE ? OR u.login LIKE ? OR st.email LIKE ?)';$like='%'.$qText.'%';array_push($params,$like,$like,$like,$like,$like);}if($groupFilter){$sql.=' AND st.group_id=?';$params[]=$groupFilter;}if(in_array($statusFilter,['active','inactive'],true)){$sql.=' AND st.status=?';$params[]=$statusFilter;}$sql.=' ORDER BY st.surname,st.name';$q=$pdo->prepare($sql);$q->execute($params);$rows=$q->fetchAll();include '../includes/header.php';?>
<div class="panel"><div class="section-head"><h2>Поиск и фильтры</h2><a class="btn" href="?action=add">+ Добавить студента</a></div><form method="get" class="filters"><input name="q" value="<?=htmlspecialchars($qText)?>" placeholder="🔍 ФИО, логин или email"><select name="group"><option value="0">Все группы</option><?php foreach($groups as $g):?><option value="<?=$g['id']?>" <?=$groupFilter==$g['id']?'selected':''?>><?=htmlspecialchars($g['name'])?></option><?php endforeach;?></select><select name="status"><option value="">Любой статус</option><option value="active" <?=$statusFilter==='active'?'selected':''?>>Активные</option><option value="inactive" <?=$statusFilter==='inactive'?'selected':''?>>Неактивные</option></select><button class="btn">Применить</button><a class="btn secondary" href="students.php">Сбросить</a><span class="result-count">Найдено: <?=count($rows)?></span></form></div>
<?php if(isset($_GET['action'])||$edit):?><div class="panel" style="margin-top:20px"><h2><?=$edit?'Редактировать':'Новый студент'?></h2><form method="post"><input type="hidden" name="id" value="<?=$edit['id']??0?>"><div class="form-grid"><div class="form-group"><label>Фамилия</label><input name="surname" required value="<?=htmlspecialchars($edit['surname']??'')?>"></div><div class="form-group"><label>Имя</label><input name="name" required value="<?=htmlspecialchars($edit['name']??'')?>"></div><div class="form-group"><label>Отчество</label><input name="patronymic" value="<?=htmlspecialchars($edit['patronymic']??'')?>"></div><div class="form-group"><label>Группа</label><select name="group_id" required><?php foreach($groups as $g):?><option value="<?=$g['id']?>" <?=($edit['group_id']??0)==$g['id']?'selected':''?>><?=htmlspecialchars($g['name'])?></option><?php endforeach;?></select></div><div class="form-group"><label>Телефон</label><input name="phone" value="<?=htmlspecialchars($edit['phone']??'')?>"></div><div class="form-group"><label>Email</label><input type="email" name="email" value="<?=htmlspecialchars($edit['email']??'')?>"></div><?php if($edit):?><div class="form-group"><label>Статус</label><select name="status"><option value="active" <?=($edit['status']??'')==='active'?'selected':''?>>Активен</option><option value="inactive" <?=($edit['status']??'')==='inactive'?'selected':''?>>Неактивен</option></select></div><?php else:?><div class="form-group"><label>Логин</label><input name="login" required></div><div class="form-group"><label>Пароль</label><input type="password" name="password" minlength="6" required></div><?php endif;?></div><br><button class="btn">Сохранить</button> <a class="btn secondary" href="students.php">Отмена</a></form></div><?php endif;?>
<div class="panel" style="margin-top:20px"><div class="table-wrap"><table><tr><th>ФИО</th><th>Логин</th><th>Группа</th><th>Телефон</th><th>Email</th><th>Статус</th><th></th></tr><?php foreach($rows as $r):?><tr><td><b><?=htmlspecialchars(trim("$r[surname] $r[name] $r[patronymic]"))?></b></td><td><?=htmlspecialchars($r['login'])?></td><td><?=htmlspecialchars($r['group_name'])?></td><td><?=htmlspecialchars($r['phone'])?></td><td><?=htmlspecialchars($r['email'])?></td><td><span class="badge <?=$r['status']==='active'?'present':'absent'?>"><?=$r['status']==='active'?'Активен':'Неактивен'?></span></td><td class="actions"><a class="btn secondary" href="?edit=<?=$r['id']?>">Изменить</a><a class="btn danger" href="?delete=<?=$r['id']?>" onclick="return confirm('Удалить студента и его аккаунт?')">Удалить</a></td></tr><?php endforeach;?></table></div></div>
<?php include '../includes/footer.php';?>
